import React, { useState } from "react";
import api from "../services/api";
import { Attendee, CreateEventFormProps, EventPayload } from "../types/event";

export default function CreateEventForm({ onCreated }: CreateEventFormProps) {
  const [name, setName] = useState("");
  const [venue, setVenue] = useState("");
  const [start, setStart] = useState(""); // datetime-local string
  const [end, setEnd] = useState("");
  const [attendees, setAttendees] = useState<Attendee[]>([]);

  const addAttendee = () => setAttendees(prev => [...prev, { name: "", email: "" }]);

  const updateAttendee = (index: number, field: keyof Attendee, value: string) => {
    setAttendees(prev =>
      prev.map((a, i) => (i === index ? { ...a, [field]: value } : a))
    );
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();

    const payload: EventPayload = {
      name,
      venue,
      startTime: new Date(start).toISOString(),
      endTime: new Date(end).toISOString(),
      attendees,
    };

    try {
      await api.post("/api/events", payload);
      onCreated?.(); // call only if provided
      // Optionally reset form
      setName("");
      setVenue("");
      setStart("");
      setEnd("");
      setAttendees([]);
    } catch (error) {
      console.error("Failed to create event", error);
    }
  };

  return (
    <form onSubmit={submit}>
      <input
        value={name}
        onChange={e => setName(e.target.value)}
        placeholder="Event name"
        required
      />
      <input
        type="datetime-local"
        value={start}
        onChange={e => setStart(e.target.value)}
        required
      />
      <input
        type="datetime-local"
        value={end}
        onChange={e => setEnd(e.target.value)}
        required
      />
      <input
        value={venue}
        onChange={e => setVenue(e.target.value)}
        placeholder="Venue"
        required
      />
      <button type="button" onClick={addAttendee}>
        Add Attendee
      </button>

      {attendees.map((a, i) => (
        <div key={i}>
          <input
            placeholder="Name"
            value={a.name}
            onChange={e => updateAttendee(i, "name", e.target.value)}
            required
          />
          <input
            placeholder="Email"
            type="email"
            value={a.email}
            onChange={e => updateAttendee(i, "email", e.target.value)}
            required
          />
        </div>
      ))}

      <button type="submit">Create Event</button>
    </form>
  );
}
